#!/usr/bin/env node
// Agentic Harness gate runner. Generated by Agentic Harness; re-export instead of editing.
//
//   node .harness/gates.mjs start   <operation> <task-slug>   begin an operation (checks earlier gates)
//   node .harness/gates.mjs check   <operation> <task-slug>   run the operation's automated gates
//   node .harness/gates.mjs approve <operation> <task-slug> [notes]   HUMAN ONLY: record approval
//   node .harness/gates.mjs status  <task-slug>
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

const root = spawnSync('git', ['rev-parse', '--show-toplevel'], { encoding: 'utf8' }).stdout.trim() || process.cwd();
process.chdir(root);
const pipeline = JSON.parse(fs.readFileSync('.harness/pipeline.json', 'utf8'));
const [cmd, a1, a2, ...rest] = process.argv.slice(2);

const fail = (msg) => {
  console.error(`✗ ${msg}`);
  process.exit(1);
};
const git = (args) => spawnSync('git', args, { encoding: 'utf8' });
const readJson = (p, fallback) => {
  try {
    return JSON.parse(fs.readFileSync(p, 'utf8'));
  } catch {
    return fallback;
  }
};
const writeJson = (p, v) => {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, `${JSON.stringify(v, null, 2)}\n`);
};

function opByKey(key) {
  const op = pipeline.operations.find((o) => o.key === key);
  if (!op) fail(`Unknown operation "${key}". Known: ${pipeline.operations.map((o) => o.key).join(', ')}`);
  return op;
}
function slugOk(slug) {
  if (!slug || !/^[a-z0-9][a-z0-9-]{1,60}$/.test(slug)) fail('Task slug must be lowercase letters, digits and dashes (e.g. "add-login-rate-limit").');
  return slug;
}
const workDir = (slug) => `.harness/work/${slug}`;
const statusPath = (slug) => `${workDir(slug)}/status.json`;
const hasHumanGate = (op) => op.gates.some((g) => g.type === 'human_approval' && g.enabled !== false);

/* ---------------------------------------------------------------- artifacts */

const norm = (s) => s.replace(/[*_`]/g, '').trim().toLowerCase();
function sections(md) {
  const lines = md.split('\n');
  const heads = [];
  let fence = false;
  lines.forEach((l, i) => {
    if (/^\s*(```|~~~)/.test(l)) fence = !fence;
    if (fence) return;
    const m = /^(#{1,6})\s+(.+?)\s*#*\s*$/.exec(l);
    if (m) heads.push({ level: m[1].length, title: m[2], line: i });
  });
  return heads.map((h, idx) => {
    let end = lines.length;
    for (let j = idx + 1; j < heads.length; j++) if (heads[j].level <= h.level) { end = heads[j].line; break; }
    return { title: h.title, body: lines.slice(h.line + 1, end).join('\n') };
  });
}

/** Subset of JSON Schema: type, required, properties, items, enum, const, minItems, minLength, pattern, minimum. */
function schemaErrors(schema, value, at = '') {
  const errs = [];
  if (!schema || typeof schema !== 'object') return errs;
  if (schema.const !== undefined && JSON.stringify(value) !== JSON.stringify(schema.const)) errs.push(`${at || '(root)'} must equal ${JSON.stringify(schema.const)}`);
  if (schema.enum && !schema.enum.some((e) => JSON.stringify(e) === JSON.stringify(value))) errs.push(`${at || '(root)'} must be one of ${schema.enum.join(', ')}`);
  const t = schema.type;
  const typeOf = (v) => (Array.isArray(v) ? 'array' : v === null ? 'null' : Number.isInteger(v) ? 'integer' : typeof v);
  if (t) {
    const types = Array.isArray(t) ? t : [t];
    const actual = typeOf(value);
    if (!types.includes(actual) && !(actual === 'integer' && types.includes('number'))) {
      errs.push(`${at || '(root)'} must be ${types.join('|')}`);
      return errs;
    }
  }
  if (typeof value === 'string') {
    if (schema.minLength && value.length < schema.minLength) errs.push(`${at} must have at least ${schema.minLength} characters`);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) errs.push(`${at} must match /${schema.pattern}/`);
  }
  if (typeof value === 'number' && schema.minimum !== undefined && value < schema.minimum) errs.push(`${at} must be >= ${schema.minimum}`);
  if (Array.isArray(value)) {
    if (schema.minItems && value.length < schema.minItems) errs.push(`${at} must have at least ${schema.minItems} item(s)`);
    if (schema.items) value.forEach((v, i) => errs.push(...schemaErrors(schema.items, v, `${at}/${i}`)));
  }
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    for (const r of schema.required ?? []) if (!(r in value)) errs.push(`${at || '(root)'} is missing required property "${r}"`);
    for (const [k, s] of Object.entries(schema.properties ?? {})) if (k in value) errs.push(...schemaErrors(s, value[k], `${at}/${k}`));
  }
  return errs;
}

function validateArtifact(c, slug) {
  const file = `${workDir(slug)}/${c.path}`;
  if (!fs.existsSync(file)) return [`Missing artifact ${file}`];
  const content = fs.readFileSync(file, 'utf8');
  const errs = [];
  if (!content.trim()) return [`${file} is empty`];
  if (content.length < (c.minChars ?? 0)) errs.push(`${file} has ${content.length} chars; needs ${c.minChars}`);
  for (const p of c.requiredPatterns ?? []) if (!new RegExp(p.pattern, 'im').test(content)) errs.push(`${file} must contain ${p.description}`);
  if (c.format === 'markdown') {
    const secs = sections(content);
    for (const h of c.requiredHeadings ?? []) {
      const s = secs.find((x) => norm(x.title) === norm(h));
      if (!s) errs.push(`${file} is missing section "${h}"`);
      else if (!s.body.replace(/<!--[\s\S]*?-->/g, '').trim()) errs.push(`${file} section "${h}" is empty`);
    }
    if (c.rejectPlaceholders !== false) {
      const m = /\b(TODO|TBD|FIXME|lorem ipsum|XXX)\b/.exec(content);
      if (m) errs.push(`${file} contains placeholder "${m[0]}"`);
    }
  } else {
    let doc;
    try {
      doc = JSON.parse(content);
    } catch (e) {
      return [`${file} is not valid JSON: ${e.message}`];
    }
    errs.push(...schemaErrors(c.jsonSchema, doc).map((e) => `${file} ${e}`));
  }
  return errs;
}

function findArtifact(id, slug) {
  for (const o of pipeline.operations) {
    const c = o.artifacts.find((x) => x.id === id);
    if (c) return { contract: c, file: `${workDir(slug)}/${c.path}` };
  }
  return null;
}

function select(rootValue, expr) {
  let cur = [rootValue];
  for (const raw of expr.split('.').filter(Boolean)) {
    const m = /^([\w$-]+)(\[\]|\[\?([\w$-]+)\s*==\s*([^\]]+)\])?$/.exec(raw);
    if (!m) throw new Error(`bad path ${expr}`);
    const [, key, br, fk, fv] = m;
    const next = [];
    for (const v of cur) {
      if (!v || typeof v !== 'object' || v[key] === undefined) continue;
      const child = v[key];
      if (!br) next.push(child);
      else if (Array.isArray(child)) next.push(...(br === '[]' ? child : child.filter((it) => it && String(it[fk]) === fv.trim().replace(/^['"]|['"]$/g, ''))));
    }
    cur = next;
  }
  return cur;
}

/* -------------------------------------------------------------------- gates */

function runGates(op, slug, status) {
  const results = [];
  const order = { artifacts: 0, json_assert: 1, diff_scope: 2, command: 3, human_approval: 4 };
  for (const g of [...op.gates].filter((x) => x.enabled !== false).sort((a, b) => order[a.type] - order[b.type])) {
    if (g.type === 'artifacts') {
      const errs = op.artifacts.flatMap((c) => validateArtifact(c, slug));
      results.push({ g, ok: !errs.length, detail: errs.join('\n') });
    } else if (g.type === 'json_assert') {
      const found = findArtifact(g.artifact, slug);
      let doc = null;
      try {
        doc = JSON.parse(fs.readFileSync(found.file, 'utf8'));
      } catch {
        results.push({ g, ok: false, detail: `${g.artifact} missing or invalid` });
        continue;
      }
      const bad = [];
      for (const a of g.assertions) {
        const vals = select(doc, a.path);
        const count = vals.length === 1 && Array.isArray(vals[0]) ? vals[0].length : vals.length;
        const first = JSON.stringify(vals[0]);
        const want = JSON.stringify(a.value);
        const ok = {
          exists: vals.length > 0,
          eq: first === want,
          neq: first !== want,
          in: Array.isArray(a.value) && a.value.some((x) => JSON.stringify(x) === first),
          count_eq: count === Number(a.value),
          count_lte: count <= Number(a.value),
          count_gte: count >= Number(a.value),
        }[a.op];
        if (!ok) bad.push(a.message);
      }
      results.push({ g, ok: !bad.length, detail: bad.join('\n') });
    } else if (g.type === 'diff_scope') {
      const found = findArtifact(g.planArtifact, slug);
      let allowed;
      try {
        allowed = select(JSON.parse(fs.readFileSync(found.file, 'utf8')), g.filesPath).flat().map((f) => String(f).replace(/^\.\//, ''));
      } catch {
        results.push({ g, ok: false, detail: `approved plan ${g.planArtifact} not found` });
        continue;
      }
      const changed = new Set([
        ...git(['diff', '--name-only', status.baseCommit]).stdout.split('\n'),
        ...git(['ls-files', '--others', '--exclude-standard']).stdout.split('\n'),
      ]);
      const extra = (g.alwaysAllowed ?? []).map((x) => new RegExp(`^${x.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*\*\/?/g, '.*').replace(/\*/g, '[^/]*')}$`));
      const out = [...changed].filter((f) => f && !f.startsWith('.harness/') && !allowed.includes(f) && !extra.some((re) => re.test(f)));
      results.push({ g, ok: !out.length, detail: out.length ? `Out of plan scope:\n${out.map((f) => `  - ${f}`).join('\n')}` : '' });
    } else if (g.type === 'command') {
      const command = g.check ? pipeline.repoChecks?.[g.check] : g.command;
      if (!command) {
        results.push({ g, ok: !(g.required ?? true), detail: g.check ? `no "${g.check}" check configured${g.required === false ? ' (optional, skipped)' : ''}` : 'no command' });
        continue;
      }
      const r = spawnSync('bash', ['-c', command], { encoding: 'utf8', timeout: (g.timeoutSeconds ?? 600) * 1000 });
      const code = r.status ?? 1;
      results.push({ g, ok: code === (g.expectExitCode ?? 0), detail: `$ ${command} → exit ${code}\n${`${r.stdout}${r.stderr}`.trim().split('\n').slice(-40).join('\n')}` });
    }
  }
  return results;
}

/* ----------------------------------------------------------------- commands */

if (cmd === 'status') {
  const slug = slugOk(a1);
  console.log(JSON.stringify(readJson(statusPath(slug), {}), null, 2));
  process.exit(0);
}
if (!['start', 'check', 'approve'].includes(cmd)) {
  fail('Usage: node .harness/gates.mjs <start|check|approve> <operation> <task-slug> [notes] | status <task-slug>');
}
const op = opByKey(a1);
const slug = slugOk(a2);
const status = readJson(statusPath(slug), { baseCommit: null, ops: {} });

if (cmd === 'start') {
  if (!status.baseCommit) status.baseCommit = git(['rev-parse', 'HEAD']).stdout.trim();
  const idx = pipeline.operations.findIndex((o) => o.key === op.key);
  for (const prev of pipeline.operations.slice(0, idx)) {
    const s = status.ops[prev.key];
    if (!s?.checked) fail(`Operation "${prev.key}" has not passed its gates for "${slug}". Run /harness-${prev.key} first.`);
    if (hasHumanGate(prev) && !s.approved) fail(`Operation "${prev.key}" is waiting for human approval. A human must run: node .harness/gates.mjs approve ${prev.key} ${slug} "notes"`);
  }
  for (const input of op.inputs ?? []) {
    const found = findArtifact(input.artifact, slug);
    if (input.required && (!found || !fs.existsSync(found.file))) fail(`Required input "${input.artifact}" is missing.`);
  }
  status.ops[op.key] = { ...(status.ops[op.key] ?? {}), started: new Date().toISOString(), checked: false, approved: false };
  writeJson(statusPath(slug), status);
  writeJson('.harness/state.json', { operation: op.key, slug });
  console.log(`✓ Started "${op.name}" for ${slug}. Artifacts go in ${workDir(slug)}/:`);
  for (const c of op.artifacts) console.log(`  - ${workDir(slug)}/${c.path} (${c.format})`);
  process.exit(0);
}

if (cmd === 'check') {
  const results = runGates(op, slug, status);
  for (const r of results) console.log(`${r.ok ? '✓ PASS' : '✗ FAIL'}  ${r.g.name}${r.detail ? `\n${r.detail.split('\n').map((l) => `    ${l}`).join('\n')}` : ''}`);
  const ok = results.every((r) => r.ok);
  status.ops[op.key] = { ...(status.ops[op.key] ?? {}), checked: ok, checkedAt: new Date().toISOString(), approved: false };
  writeJson(statusPath(slug), status);
  if (!ok) fail('Gates failed. Fix the causes above and run the check again.');
  const human = op.gates.find((g) => g.type === 'human_approval' && g.enabled !== false);
  if (human) {
    console.log(`\n■ HUMAN GATE: ${human.name}\n  ${human.instructions}`);
    for (const c of human.checklist ?? []) console.log(`  [ ] ${c}`);
    console.log(`\n  STOP. Ask the user to review. They approve by running:\n  node .harness/gates.mjs approve ${op.key} ${slug} "notes"`);
  } else {
    console.log('\n✓ All gates passed.');
  }
  process.exit(0);
}

if (cmd === 'approve') {
  const s = status.ops[op.key];
  if (!s?.checked) fail(`"${op.key}" has not passed its automated gates; nothing to approve.`);
  const notes = rest.join(' ').trim();
  status.ops[op.key] = { ...s, approved: true, approvedAt: new Date().toISOString(), notes };
  writeJson(statusPath(slug), status);
  if (notes) fs.appendFileSync(`${workDir(slug)}/decisions.md`, `\n## ${op.name} — ${new Date().toISOString()}\n${notes}\n`);
  console.log(`✓ Approved "${op.name}" for ${slug}.${notes ? ' Notes recorded as binding decisions.' : ''}`);
}
